def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]: out[r][c]=0
    rem={(r,c) for r in range(h) for c in range(w) if g[r][c]}
    # greedy exact cover: repeatedly take topmost-leftmost uncovered cell, must be in unique forced piece;
    # use backtracking to be safe
    pieces=[]
    for r in range(h-1):
        for c in range(w-1):
            box=[(r+a,c+b) for a in(0,1) for b in(0,1)]
            boxset=set(box)
            if boxset<=rem: pieces.append((1,boxset))
            for miss in box:
                rest=boxset-{miss}
                if rest<=rem and miss not in rem:
                    pieces.append((2,rest))
    # map piece->color
    def color(kind,ps):
        if kind==1: return 1
        r=min(p[0] for p in ps); c=min(p[1] for p in ps)
        miss=(r if (r,c) not in ps else r+1, c if (r,c+1) not in ps else c+1)
        # miss corner: TL->2 BL->3 TR->4 BR->5
        dr = miss[0]-r; dc = miss[1]-c
        return {(0,0):2,(1,0):3,(0,1):4,(1,1):5}[(dr,dc)]
    sol=[]
    def rec(rem):
        if not rem: return True
        p0=min(rem)
        for kind,ps in pieces:
            if p0 in ps and ps<=rem:
                sol.append((kind,ps))
                if rec(rem-ps): return True
                sol.pop()
        return False
    rec(rem)
    for kind,ps in sol:
        col=color(kind,ps)
        for (r,c) in ps: out[r][c]=col
    return out

